CREATE OR REPLACE FUNCTION public.resolve_sharawla_commercial_entitlement_cloud_v1(p_business_id uuid, p_feature_code text, p_at_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_b public.businesses%rowtype; v_f public.features%rowtype; v_profile text; v_pf boolean; v_af boolean;
 v_pkg record; v_add record; v_diag jsonb := '[]'::jsonb;
begin
 if p_at_time is null then return jsonb_build_object('entitled',false,'reason_code','CONFIG_LOAD_FAILED','error_detail','AT_TIME_REQUIRED','resolver_version',1); end if;
 select * into v_b from public.businesses where id=p_business_id;
 if not found then return jsonb_build_object('entitled',false,'reason_code','BUSINESS_NOT_FOUND','business_id',p_business_id,'feature_code',p_feature_code,'resolver_version',1); end if;
 if not v_b.active then return jsonb_build_object('entitled',false,'reason_code','BUSINESS_INACTIVE','business_id',p_business_id,'feature_code',p_feature_code,'resolver_version',1); end if;
 select * into v_f from public.features where code=p_feature_code;
 if not found then return jsonb_build_object('entitled',false,'reason_code','FEATURE_UNKNOWN','business_id',p_business_id,'feature_code',p_feature_code,'resolver_version',1); end if;
 if not v_f.implemented then return jsonb_build_object('entitled',false,'reason_code','NOT_IMPLEMENTED','business_id',p_business_id,'feature_code',p_feature_code,'resolver_version',1); end if;
 if not v_f.active then return jsonb_build_object('entitled',false,'reason_code','INACTIVE','business_id',p_business_id,'feature_code',p_feature_code,'resolver_version',1); end if;
 select pp.code,coalesce(pf.enabled,false) into v_profile,v_pf from public.pos_profiles pp left join public.profile_features pf on pf.profile_id=pp.id and pf.feature_id=v_f.id where pp.id=v_b.pos_profile_id;
 if v_profile is null or not coalesce(v_pf,false) then return jsonb_build_object('entitled',false,'reason_code','PROFILE_INELIGIBLE','business_id',p_business_id,'feature_code',p_feature_code,'profile',v_profile,'resolver_version',1); end if;
 if v_b.activity_category_id is not null then
   select acf.enabled into v_af from public.activity_category_features acf where acf.activity_category_id=v_b.activity_category_id and acf.feature_id=v_f.id;
   if found and v_af=false then return jsonb_build_object('entitled',false,'reason_code','ACTIVITY_INELIGIBLE','business_id',p_business_id,'feature_code',p_feature_code,'profile',v_profile,'resolver_version',1); end if;
 end if;
 if v_f.feature_class='core' then return jsonb_build_object('entitled',true,'reason_code','CORE_INCLUDED','entitlement_source','core','business_id',p_business_id,'feature_code',p_feature_code,'profile',v_profile,'evaluation_time',p_at_time,'resolver_version',1); end if;
 select p.id package_id,p.code,p.version,e.id entitlement_id,e.starts_at,e.expires_at into v_pkg
 from public.business_package_entitlements e join public.commercial_packages p on p.id=e.package_id join public.commercial_package_features pf on pf.package_id=p.id and pf.feature_id=v_f.id
 where e.business_id=p_business_id and e.status='active' and e.starts_at<=p_at_time and (e.expires_at is null or e.expires_at>p_at_time) and p.lifecycle_status='published' and p.active=true order by e.starts_at desc limit 1;
 if found then return jsonb_build_object('entitled',true,'reason_code','PACKAGE_ENTITLED','entitlement_source','package','business_id',p_business_id,'feature_code',p_feature_code,'package_id',v_pkg.package_id,'package_code',v_pkg.code,'package_version',v_pkg.version,'entitlement_id',v_pkg.entitlement_id,'effective_from',v_pkg.starts_at,'effective_until',v_pkg.expires_at,'profile',v_profile,'evaluation_time',p_at_time,'resolver_version',1); end if;
 select a.id entitlement_id,a.starts_at,a.expires_at into v_add from public.business_paid_addons a where a.business_id=p_business_id and a.feature_id=v_f.id and a.status='active' and a.starts_at<=p_at_time and (a.expires_at is null or a.expires_at>p_at_time) order by a.starts_at desc limit 1;
 if found then return jsonb_build_object('entitled',true,'reason_code','PAID_ADDON_ENTITLED','entitlement_source','paid_addon','business_id',p_business_id,'feature_code',p_feature_code,'entitlement_id',v_add.entitlement_id,'effective_from',v_add.starts_at,'effective_until',v_add.expires_at,'profile',v_profile,'evaluation_time',p_at_time,'resolver_version',1); end if;
 select coalesce(jsonb_agg(x),'[]'::jsonb) into v_diag from (
   select jsonb_build_object('source','package','status',e.status,'starts_at',e.starts_at,'expires_at',e.expires_at,'package_status',p.lifecycle_status,'package_active',p.active) x
   from public.business_package_entitlements e join public.commercial_packages p on p.id=e.package_id join public.commercial_package_features pf on pf.package_id=p.id and pf.feature_id=v_f.id where e.business_id=p_business_id
   union all
   select jsonb_build_object('source','paid_addon','status',a.status,'starts_at',a.starts_at,'expires_at',a.expires_at) from public.business_paid_addons a where a.business_id=p_business_id and a.feature_id=v_f.id
 ) q;
 return jsonb_build_object('entitled',false,'reason_code','NOT_ENTITLED','entitlement_source','none','business_id',p_business_id,'feature_code',p_feature_code,'profile',v_profile,'evaluation_time',p_at_time,'grant_diagnostics',v_diag,'resolver_version',1);
exception when others then return jsonb_build_object('entitled',false,'reason_code','CONFIG_LOAD_FAILED','error_detail','COMMERCIAL_RESOLVER_EXCEPTION','business_id',p_business_id,'feature_code',p_feature_code,'resolver_version',1); end; $function$
